    "health_status",
    "severity",
    "needs_human_review",
    "review_focus",
    "evidence",
    "limitations"
  ]
}

parameters.jsCode:
const request = $('Normalize Request').first().json;

const raw = $input.first().json;

// Internal trace only: never return tool payloads or agent reasoning to the caller.
const toolNames = ['get_health_report', 'get_review_events'];
function parseObservation(value) {
  if (typeof value === 'string') {
    try { return parseObservation(JSON.parse(value)); } catch { return null; }
  }
  if (!value || typeof value !== 'object') return null;
  if (Array.isArray(value)) {
    // LangChain may wrap JSON in text content blocks.
    if (value.length && value.every(x => x && x.type === 'text' && typeof x.text === 'string')) {
      const parsed = value.map(x => parseObservation(x.text));
      return parsed.every(x => x !== null) ? parsed : null;
    }
    return value;
  }
  if (value.type === 'text' && typeof value.text === 'string') return parseObservation(value.text);
  return value;
}
function usable(value) {
  if (!value || typeof value !== 'object') return false;
  if (Array.isArray(value)) return value.length > 0 && value.every(usable);
  if (value.error || value.accepted === false || value.success === false ||
      (typeof value.statusCode === 'number' && (value.statusCode < 200 || value.statusCode >= 300))) return false;
  if (value.body !== undefined && typeof value.statusCode === 'number') return usable(value.body);
  return Object.keys(value).length > 0;
}
function walk(value, visit) {
  if (!value || typeof value !== 'object') return;
  for (const [key, val] of Object.entries(value)) {
    visit(key, val);
    if (val && typeof val === 'object') walk(val, visit);
  }
}
const retrieved = new Map();
for (const step of Array.isArray(raw.intermediateSteps) ? raw.intermediateSteps : []) {
  const name = step?.action?.tool;
  if (!toolNames.includes(name)) continue;
  const payload = parseObservation(step.observation);
  if (!usable(payload)) continue;
  let wrongAstronaut = false;
  walk(payload, (key, val) => {
    if (key === 'astronaut_id' && typeof val === 'string' && val !== request.astronaut_id) wrongAstronaut = true;
  });
  if (wrongAstronaut) return fail('TOOL_ASTRONAUT_MISMATCH');
  if (!retrieved.has(name)) retrieved.set(name, []);
  retrieved.get(name).push(payload);
}
function containsReference(payloads, field, expected) {
  if (expected === null) return true;
  let found = false;
  for (const payload of payloads) walk(payload, (key, val) => {
    if (val === expected && (field === 'event_id' ? key === 'event_id' : /(?:timestamp|_at$|^start$|^end$|^time$)/i.test(key))) found = true;
  });
  return found;
}

function fail(reason) {
  return [{
    json: {
      accepted: false,
      schema_version: "1.0",
      request_id: request.request_id,
      astronaut_id: request.astronaut_id,
      error: "INVALID_AI_RESPONSE",
      message: "The health explanation could not be generated safely.",
      validation_reason: reason,
      http_status: 502
    }
  }];
}

let result = raw.output ?? raw;

if (typeof result === "string") {
  try {
    result = JSON.parse(result);
  } catch {
    return fail("INVALID_JSON");
  }
}

if (!result || typeof result !== "object" || Array.isArray(result)) {
  return fail("INVALID_OUTPUT");
}

// Convert Gemini-safe internal scalar encoding back to the public API contract.
const decodeUnknown = v => v === 'UNKNOWN' ? null : v;
result.health_status = decodeUnknown(result.health_status);
result.severity = decodeUnknown(result.severity);
if (!['TRUE', 'FALSE', 'UNKNOWN'].includes(result.needs_human_review)) return fail('INVALID_REVIEW_ENCODING');
result.needs_human_review = result.needs_human_review === 'UNKNOWN' ? null : result.needs_human_review === 'TRUE';
if (Array.isArray(result.evidence)) {
  result.evidence = result.evidence.map(e => e && typeof e === 'object' && !Array.isArray(e) ? {
    ...e, event_id: decodeUnknown(e.event_id), timestamp: decodeUnknown(e.timestamp)
  } : e);
}

if (result.request_id !== request.request_id) {
  return fail("REQUEST_ID_MISMATCH");
}

if (result.astronaut_id !== request.astronaut_id) {
  return fail("ASTRONAUT_ID_MISMATCH");
}

if (result.request_type !== request.request_type) {
  return fail("REQUEST_TYPE_MISMATCH");
}

const allowedStatuses = [
  "SUCCESS",
  "PARTIAL",
  "UNAVAILABLE",
  "OUT_OF_SCOPE"
];

if (!allowedStatuses.includes(result.status)) {
  return fail("INVALID_STATUS");
}

if (
  typeof result.summary !== "string" ||
  !Array.isArray(result.key_findings) ||
  !Array.isArray(result.review_focus) ||
  !Array.isArray(result.evidence) ||
  !Array.isArray(result.limitations)
) {
  return fail("INVALID_RESPONSE_STRUCTURE");
}

const nullableString = v => v === null || typeof v === "string";
const stringArray = v => Array.isArray(v) && v.every(x => typeof x === "string");
if (!nullableString(result.health_status) || !nullableString(result.severity) ||
    !(result.needs_human_review === null || typeof result.needs_human_review === "boolean") ||
    !stringArray(result.key_findings) || result.key_findings.length > 5 ||
    !stringArray(result.review_focus) || result.review_focus.length > 3 ||
    !stringArray(result.limitations) ||
    !result.evidence.every(e => e && ["get_health_report", "get_review_events"].includes(e.source) && nullableString(e.event_id) && nullableString(e.timestamp))) {
  return fail("INVALID_FIELD_TYPES");
}

if (
  ["SUCCESS", "PARTIAL"].includes(result.status) &&
  result.evidence.length === 0
) {
  return fail("MISSING_EVIDENCE");
}

if (result.summary.trim().length === 0 || result.summary.trim().split(/\s+/).length > 80) {
  return fail("INVALID_SUMMARY");
}
if (result.status === "SUCCESS" || result.status === "PARTIAL") {
  if (request.request_type === "HEALTH_BRIEFING" && result.status === "SUCCESS" &&
      !toolNames.every(name => retrieved.has(name))) return fail("MISSING_BRIEFING_TOOLS");
  for (const evidence of result.evidence) {
    const payloads = retrieved.get(evidence.source);
    if (!payloads || !containsReference(payloads, 'event_id', evidence.event_id) ||
        !containsReference(payloads, 'timestamp', evidence.timestamp)) return fail("UNVERIFIED_EVIDENCE");
  }
}
if (result.status === "OUT_OF_SCOPE" && (result.evidence.length || result.key_findings.length ||
    result.review_focus.length || result.health_status !== null || result.severity !== null ||
    result.needs_human_review !== null)) return fail("OUT_OF_SCOPE_HEALTH_DATA");

if (result.status === "UNAVAILABLE") {
  return [{
    json: {
      accepted: false,
      schema_version: "1.0",
      request_id: request.request_id,
      astronaut_id: request.astronaut_id,
      error: "HEALTH_DATA_UNAVAILABLE",
      message: "Required health data could not be retrieved.",
      http_status: 503
    }
  }];
}

// Preserve the existing external response contract. Missing metadata is unknown, not live.
const freshnessLimitations = [];
if (result.status === "SUCCESS" || result.status === "PARTIAL") {
  for (const [name, payloads] of retrieved) {
    const seen = new Set();
    for (const payload of payloads) walk(payload, (key, value) => {
      if (typeof value === "string" && value.trim()) seen.add(key);
    });
    if (!seen.has("last_updated_at") || !seen.has("data_freshness"))
      freshnessLimitations.push(`${name}: backend freshness metadata is incomplete or unavailable; live status is not established.`);
    if (!seen.has("source")) freshnessLimitations.push(`${name}: backend source metadata is unavailable.`);
  }
  // The exact Earth sync field is not yet agreed. Do not guess its name or semantics.
  freshnessLimitations.push("Earth synchronization of the current data is not independently verified by this assistant.");
}

return [{
  json: {
    accepted: true,
    schema_version: "1.0",
    request_id: request.request_id,
    astronaut_id: request.astronaut_id,
    request_type: request.request_type,
    status: result.status,
    summary: result.summary,
    key_findings: result.key_findings,
    health_status: result.health_status ?? null,
    severity: result.severity ?? null,
    needs_human_review: result.needs_human_review ?? null,
    review_focus: result.review_focus,
    evidence: result.evidence,
    limitations: [...new Set([...result.limitations, ...freshnessLimitations, "Synthetic simulator data; research prototype, not a medical device."])],
    generated_at: new Date().toISOString(),
    http_status: 200
  }
}];

